{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#0f1113;--card:#0f1720;--muted:#9aa4b2;--accent:#8dd7d1;--glass:rgba(255,255,255,0.03);}
    html,body{height:100%;margin:0;font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,"Helvetica Neue",Arial;color:#e6eef3;background:linear-gradient(180deg,#071018 0%,#0f1720 60%);}
    header{display:flex;justify-content:space-between;align-items:center;padding:20px 28px;background:linear-gradient(90deg,rgba(255,255,255,0.02),transparent);backdrop-filter:blur(6px);}
    .brand{display:flex;align-items:center;gap:12px}
    .logo{width:44px;height:44px;background:linear-gradient(135deg,var(--accent),#6bd3c8);border-radius:10px;display:grid;place-items:center;color:#042126;font-weight:700}
    nav a{color:var(--muted);text-decoration:none;margin-left:18px;font-weight:600;font-size:14px}
    nav a.active{color:var(--accent)}
    .container{max-width:1000px;margin:36px auto;padding:28px;background:var(--glass);border-radius:14px;box-shadow:0 6px 30px rgba(2,6,9,0.6);}
    .hero{display:grid;grid-template-columns:1fr 320px;gap:28px;align-items:start}
    h1{margin:0;font-size:28px;color:#eef8f7}
    p.lead{color:var(--muted);line-height:1.5}
    .card{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:18px;border-radius:12px;border:1px solid rgba(255,255,255,0.03)}
    .meta{font-size:13px;color:var(--muted);margin-top:12px}
    .grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:18px}
    .small{font-size:13px;color:var(--muted)}
    footer{padding:20px;text-align:center;color:var(--muted);font-size:13px}
    .pattern{position:fixed;right:-120px;top:-120px;opacity:0.08;width:480px;height:480px;pointer-events:none}
    /* widget */
    .widget{margin-top:18px}
    .options{display:flex;gap:8px;flex-wrap:wrap}
    .chip{padding:8px 12px;border-radius:999px;background:rgba(255,255,255,0.02);border:1px solid rgba(255,255,255,0.02);color:var(--muted);cursor:pointer}
    .chip.active{background:linear-gradient(90deg,rgba(141,215,209,0.12),rgba(107,211,200,0.06));color:var(--accent);border-color:rgba(141,215,209,0.18)}
    .rec{margin-top:12px;padding:12px;border-radius:10px;background:rgba(255,255,255,0.02);color:#dff3f1}
    .cta{display:inline-block;margin-top:14px;padding:10px 14px;border-radius:10px;background:var(--accent);color:#042126;font-weight:700;text-decoration:none}
    @media(max-width:880px){.hero{grid-template-columns:1fr}.grid{grid-template-columns:1fr}} 
  </style>
</head>
<body>
  <div class="pattern">
    <img src="assets/img/pattern.svg" alt="pattern" style="width:100%;height:100%">
  </div>
  <header>
    <div class="brand">
      <div class="logo">SB</div>
      <div>
        <div style="font-weight:700;color:#e6eef3">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">{{CITY}}, {{STATE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="events.html">Gatherings</a>
      <a href="private-sessions.html">Private</a>
      <a href="pricing.html">Value</a>
      <a href="about.html" class="active">Our Story</a>
      <a href="faq.html">FAQ</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main class="container">
    <section class="hero">
      <div>
        <h1>Quiet craft and intentional resonance</h1>
        <p class="lead">We host guided sound gatherings that use tuned overtones, breath guidance, and carefully paced silence. Sessions are mapped to re-centering goals: to steady a busy mind, to ease muscle tension, and to move you toward clearer presence.</p>
        <div class="card">
          <div class="meta">How we think about the work</div>
          <p class="small">Sessions are designed as practical resets. They blend subtle harmonic layers with tempo and silence to encourage a shift in nervous-system tone — short enough to fit a busy day, considered enough to make a measurable difference.</p>
          <div class="grid">
            <div class="card small"><strong>Method</strong><div style="margin-top:8px">Layered Harmonics</div></div>
            <div class="card small"><strong>Format</strong><div style="margin-top:8px">Group & Private</div></div>
            <div class="card small"><strong>Length</strong><div style="margin-top:8px">30–75 minutes</div></div>
          </div>
        </div>
      </div>
      <aside>
        <div class="card">
          <div style="font-weight:700;color:#cfeeea">A moment to choose</div>
          <div class="meta">Select your present tone — we show one recommended approach.</div>
          <div class="widget">
            <div class="options" id="moodOptions">
              <div class="chip" data-mood="rattled">Rattled</div>
              <div class="chip" data-mood="foggy">Foggy</div>
              <div class="chip" data-mood="tight">Tight</div>
              <div class="chip" data-mood="open">Open</div>
            </div>
            <div class="rec" id="miniRec">Choose a mood to get a short recommendation.</div>
            <a href="book.html" class="cta" id="miniCta">{{PRIMARY_CTA_LABEL}}</a>
          </div>
        </div>
        <div style="height:12px"></div>
        <div class="card small">
          <strong>Responsible practice</strong>
          <p class="small" style="margin-top:8px">If you have epilepsy, are pregnant, have a pacemaker, or are under medical supervision for acute psychiatric conditions, consult your clinician before attending.</p>
        </div>
      </aside>
    </section>

    <section style="margin-top:24px">
      <h2 style="margin:0;color:#e9f8f6">The team & approach</h2>
      <p class="small">We blend acoustic instruments and guided breath with precise timing. Sessions are led by practitioners who hold a therapeutic posture — we listen first, then select sonic tools that match the group's tone.</p>
      <div class="grid" style="margin-top:14px">
        <div class="card small"><strong>Lead Facilitator</strong><div style="margin-top:6px">Acoustic protocols, holding the field</div></div>
        <div class="card small"><strong>Support</strong><div style="margin-top:6px">Breath guidance & integration</div></div>
        <div class="card small"><strong>Instruments</strong><div style="margin-top:6px">Bow, gongs, singing bowls, voice layers</div></div>
      </div>
    </section>
  </main>

  <footer>
    <div class="small">Questions? Call us at {{PHONE}} or email <a href="mailto:{{EMAIL}}" style="color:var(--accent);text-decoration:none">{{EMAIL}}</a></div>
    <div style="margin-top:8px">© <span style="opacity:0.7">{{BUSINESS_NAME}}</span></div>
  </footer>

  <script>
    (function(){
      const chips=document.querySelectorAll('#moodOptions .chip');
      const miniRec=document.getElementById('miniRec');
      const miniCta=document.getElementById('miniCta');
      const recMap={
        rattled:{title:'Ground & steady',desc:'A short paced wash with sustained harmonics to ease activation. 30–40 minutes.' ,cta:'Reserve a Grounding Session'},
        foggy:{title:'Focus clearing',desc:'Clearer layers and longer intervals to sharpen attention. 40–50 minutes.',cta:'Reserve a Clarity Session'},
        tight:{title:'Release wave',desc:'Deeper low-frequency emphasis to ease muscular tension. 50–75 minutes.',cta:'Reserve a Release Session'},
        open:{title:'Gentle attunement',desc:'Light textures and longer silent spaces for soft integration. 30–45 minutes.',cta:'Reserve an Attunement'}
      };
      chips.forEach(c=>c.addEventListener('click',()=>{
        chips.forEach(x=>x.classList.remove('active'));
        c.classList.add('active');
        const key=c.getAttribute('data-mood');
        const r=recMap[key];
        miniRec.innerHTML='<strong style="color:#cfeeea">'+r.title+'</strong><div style="margin-top:6px;color:var(--muted);font-size:13px">'+r.desc+'</div>';
        miniCta.textContent=r.cta;
        miniCta.href='book.html?preset='+key;
      }));
      // reveal default suggestion
      // set default to foggy
      document.querySelector('#moodOptions .chip[data-mood="foggy"]').click();
    })();
  </script>
</body>
</html>"} 
{"path":"faq.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>FAQ — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#071018;--muted:#9fb0ba;--accent:#8dd7d1}
    body{margin:0;font-family:Inter,system-ui,Segoe UI,Roboto,Arial;background:linear-gradient(180deg,#08121a 0%,#081318 100%);color:#eaf6f4}
    header{display:flex;justify-content:space-between;align-items:center;padding:18px 24px;background:rgba(255,255,255,0.02)}
    .logo{width:44px;height:44px;border-radius:10px;background:linear-gradient(135deg,var(--accent),#6bd3c8);display:grid;place-items:center;font-weight:700;color:#042126}
    nav a{margin-left:14px;color:var(--muted);text-decoration:none}
    .wrap{max-width:980px;margin:28px auto;padding:22px;background:rgba(255,255,255,0.02);border-radius:12px}
    h1{margin:0 0 8px 0}
    .qa{border-top:1px solid rgba(255,255,255,0.03);padding:16px 0;display:flex;gap:18px}
    .q{width:260px;color:var(--muted);font-weight:700}
    .a{flex:1;color:var(--muted);line-height:1.5}
    .contra{background:linear-gradient(90deg,rgba(255,0,0,0.06),transparent);padding:12px;border-radius:8px;border:1px solid rgba(255,0,0,0.06);color:#ffd6d6;margin-top:10px}
    .mixer{display:flex;gap:8px;margin-top:10px}
    .btn{padding:8px 10px;border-radius:8px;background:rgba(255,255,255,0.02);border:1px solid rgba(255,255,255,0.03);color:var(--muted);cursor:pointer}
    .btn.active{background:var(--accent);color:#042126;border-color:rgba(141,215,209,0.18)}
    footer{padding:18px;text-align:center;color:var(--muted)}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;align-items:center;gap:12px">
      <div class="logo">SB</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">{{CITY}}, {{STATE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="events.html">Gatherings</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main class="wrap">
    <h1>Frequently asked</h1>
    <p style="color:var(--muted)">Practical answers for attending and choosing a session.</p>

    <div class="qa">
      <div class="q">What should I bring?</div>
      <div class="a">A yoga mat or cushioned pad, a light blanket, and anything you use to stay comfortable (eye pillow, bolster). We provide mats upon request.</div>
    </div>

    <div class="qa">
      <div class="q">How long are sessions?</div>
      <div class="a">Group gatherings range from 30 to 75 minutes. Private sessions are scheduled for 45 to 90 minutes depending on intention. Use the mixer below to see how intensity and length pair.</div>
    </div>

    <div class="qa">
      <div class="q">Safety & contraindications</div>
      <div class="a">We take safety seriously. If you have epilepsy, certain cardiac devices, are pregnant, or are in treatment for acute psychiatric episodes, check with your medical provider before attending. Some instruments produce low frequencies and vibrations that may not be appropriate in those circumstances.
        <div class="contra">If you have specific medical concerns, email us at <a href="mailto:{{EMAIL}}" style="color:var(--accent);text-decoration:none">{{EMAIL}}</a> with details so we can advise.</div>
      </div>
    </div>

    <div style="margin-top:18px;border-top:1px solid rgba(255,255,255,0.03);padding-top:16px">
      <div style="font-weight:700;color:#e6f9f7">Sound preference mixer</div>
      <div style="color:var(--muted);margin-top:6px">Choose how you typically prefer sound: gentle, medium, or intense. Recommendations update below.</div>
      <div class="mixer" id="mixer1">
        <button class="btn" data-val="gentle">Gentle</button>
        <button class="btn" data-val="medium">Medium</button>
        <button class="btn" data-val="intense">Intense</button>
      </div>
      <div id="mixRec" style="margin-top:12px;color:var(--muted)">Select a texture to see what we recommend.</div>
    </div>

    <div style="margin-top:18px;border-top:1px solid rgba(255,255,255,0.03);padding-top:16px">
      <div style="font-weight:700;color:#e6f9f7">Another mixer — performer focus</div>
      <div style="color:var(--muted);margin-top:6px">This second control changes instrumentation emphasis and program notes.</div>
      <div class="mixer" id="mixer2">
        <button class="btn" data-val="gentle">Gentle</button>
        <button class="btn" data-val="medium">Medium</button>
        <button class="btn" data-val="intense">Intense</button>
      </div>
      <div id="mixRec2" style="margin-top:12px;color:var(--muted)">Choose a setting.</div>
    </div>

  </main>

  <footer>
    <div>Need a tailored recommendation? Call {{PHONE}} or <a href="book.html" style="color:var(--accent);text-decoration:none">Reserve a consult</a>.</div>
  </footer>

  <script>
    function setupMixer(wrapperId, outId, mapping){
      const wrap=document.getElementById(wrapperId);
      const out=document.getElementById(outId);
      wrap.addEventListener('click',e=>{
        if(!e.target.dataset.val) return;
        const val=e.target.dataset.val;
        wrap.querySelectorAll('.btn').forEach(b=>b.classList.remove('active'));
        e.target.classList.add('active');
        out.textContent=mapping[val];
      });
    }
    const map1={
      gentle:'Short formats with soft overtones and more silence. Ideal for integration and calm.',
      medium:'Balanced layering, rhythmic breath guidance, good for midday resets.',
      intense:'Longer low-frequency focus and deeper resonant instruments; expect stronger vibrational presence.'
    };
    const map2={
      gentle:'Sparser instrumentation: bowls and breath, minimal sustain.',
      medium:'Standard mix: gongs, bowls, voice layers blended for clarity.',
      intense:'Full harmonic wash: gongs and bowed tones with deeper overtones.'
    };
    setupMixer('mixer1','mixRec',map1);
    setupMixer('mixer2','mixRec2',map2);
    // set defaults
    document.querySelector('#mixer1 .btn[data-val="medium"]').click();
    document.querySelector('#mixer2 .btn[data-val="medium"]').click();
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Reserve — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#071018;--card:#0f1720;--muted:#9fb0ba;--accent:#8dd7d1}
    body{margin:0;font-family:Inter,system-ui,Segoe UI,Roboto,Arial;background:linear-gradient(180deg,#061218 0%,#071018 100%);color:#eaf6f4}
    header{display:flex;justify-content:space-between;align-items:center;padding:16px 24px;background:rgba(255,255,255,0.02)}
    .logo{width:44px;height:44px;border-radius:10px;background:linear-gradient(135deg,var(--accent),#6bd3c8);display:grid;place-items:center;font-weight:700;color:#042126}
    nav a{margin-left:14px;color:var(--muted);text-decoration:none}
    .wrap{max-width:980px;margin:28px auto;padding:22px;background:rgba(255,255,255,0.02);border-radius:12px}
    h1{margin:0}
    .cols{display:grid;grid-template-columns:1fr 360px;gap:18px;margin-top:12px}
    .panel{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:16px;border-radius:10px}
    label{display:block;font-size:13px;margin-top:10px;color:var(--muted)}
    input[type=text],input[type=email],select{width:100%;padding:10px;margin-top:6px;border-radius:8px;border:1px solid rgba(255,255,255,0.04);background:transparent;color:#eaf6f4}
    .row{display:flex;gap:8px}
    .btn{display:inline-block;padding:10px 14px;border-radius:10px;background:var(--accent);color:#042126;font-weight:700;border:none;cursor:pointer}
    .choice{display:flex;gap:8px;margin-top:10px}
    .choice button{padding:8px 10px;border-radius:8px;border:1px solid rgba(255,255,255,0.03);background:transparent;color:var(--muted);cursor:pointer}
    .choice button.active{background:var(--accent);color:#042126;border-color:rgba(141,215,209,0.18)}
    .rec{margin-top:12px;padding:12px;border-radius:8px;background:rgba(255,255,255,0.02);color:var(--muted)}
    .pill{display:inline-block;padding:6px 8px;border-radius:999px;background:rgba(255,255,255,0.02);border:1px solid rgba(255,255,255,0.03);color:var(--muted);font-size:12px}
    .meta{font-size:13px;color:var(--muted);margin-top:8px}
    @media(max-width:900px){.cols{grid-template-columns:1fr}} 
  </style>
</head>
<body>
  <header>
    <div style="display:flex;align-items:center;gap:12px">
      <div class="logo">SB</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">{{CITY}}, {{STATE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="events.html">Gatherings</a>
      <a href="pricing.html">Value</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main class="wrap">
    <h1>Reserve your session</h1>
    <p class="meta">Choose a mood, select texture and intensity, and we’ll suggest the right format. Bookings use a consultation-first approach so we match tools to your needs.</p>

    <div class="cols">
      <div>
        <div class="panel">
          <div style="font-weight:700">Mood-to-Method</div>
          <div class="meta">Pick how you feel now; the system will adapt the method and change the reserve button label.</div>
          <div class="choice" id="moodBtns" style="margin-top:10px">
            <button data-mood="rattled">Rattled</button>
            <button data-mood="foggy">Foggy</button>
            <button data-mood="tight">Tight</button>
            <button data-mood="open">Open</button>
          </div>

          <div style="margin-top:12px;font-weight:700;color:#cfeeea" id="methodName">Balanced Wash</div>
          <div class="rec" id="methodDesc">A curated mix of mid-range overtones and breath pacing to steady the nervous system. Estimated length: 40–50 min.</div>

          <div style="margin-top:12px;font-weight:700">Sound texture</div>
          <div class="meta">Two independent mixers below change program notes and instrument emphasis.</div>
          <div class="choice" id="texture1">
            <button data-val="gentle">Gentle</button>
            <button data-val="medium">Medium</button>
            <button data-val="intense">Intense</button>
          </div>
          <div class="rec" id="textureRec">Medium — balanced harmonics, moderate sustain.</div>

          <div style="margin-top:12px;font-weight:700">Performer focus</div>
          <div class="choice" id="texture2">
            <button data-val="gentle">Gentle</button>
            <button data-val="medium">Medium</button>
            <button data-val="intense">Intense</button>
          </div>
          <div class="rec" id="textureRec2">Medium — standard instrumentation.</div>

          <div style="margin-top:14px">
            <div class="pill" id="estimatedLength">Estimate: 40–50min</div>
            <div style="height:10px"></div>
            <a id="dynamicCta" class="btn" href="{{PRIMARY_CTA_URL}}" style="text-decoration:none">{{PRIMARY_CTA_LABEL}}</a>
          </div>
        </div>

        <div style="margin-top:12px" class="panel">
          <div style="font-weight:700">Note on safety</div>
          <div class="meta">If you are pregnant, have epilepsy, use a pacemaker, or are being treated for acute psychiatric disorders, consult a clinician before attending. Contact us at <a href="mailto:{{EMAIL}}" style="color:var(--accent);text-decoration:none">{{EMAIL}}</a> for guidance.</div>
        </div>
      </div>

      <aside>
        <div class="panel">
          <div style="font-weight:700">Quick reservation form</div>
          <form id="bookingForm" onsubmit="return false;" style="margin-top:8px">
            <label>Name<input type="text" id="name" placeholder="Your name"></label>
            <label>Email<input type="email" id="email" placeholder="you@example.com"></label>
            <div class="row">
              <label style="flex:1">Phone<input type="text" id="phone" placeholder="(555) 555-5555"></label>
              <label style="width:110px">Party<select id="party"><option>1</option><option>2</option><option>3</option><option>4</option></select></label>
            </div>
            <input type="hidden" id="chosenMethod" name="method" value="Balanced Wash">
            <input type="hidden" id="chosenTexture" name="texture" value="medium">
            <div style="margin-top:12px;text-align:right">
              <button class="btn" id="submitBtn">Send Request</button>
            </div>
            <div class="meta" style="margin-top:10px">We confirm availability by email and hold a reservation for 48 hours until payment completes.</div>
          </form>
        </div>
      </aside>
    </div>
  </main>

  <footer style="padding:18px;text-align:center;color:var(--muted)">Questions? Call {{PHONE}} or email <a href="mailto:{{EMAIL}}" style="color:var(--accent);text-decoration:none">{{EMAIL}}</a></footer>

  <script>
    (function(){
      // maps
      const methodMap={
        rattled:{name:'Grounding Ritual',desc:'Faster tempo, lower overtone anchor. Designed to quiet an activated nervous state.',length:'30–40min',cta:'Book a Grounding Ritual'},
        foggy:{name:'Clarity Flow',desc:'Clear interval phrasing and brighter harmonics to sharpen focus.',length:'40–50min',cta:'Book a Clarity Flow'},
        tight:{name:'Release Wave',desc:'Deep low-frequency emphasis with slower transitions to release tension.',length:'50–75min',cta:'Book a Release Wave'},
        open:{name:'Soft Attune',desc:'Gentle, airy textures and extended silent spaces for integration.',length:'30–45min',cta:'Book a Soft Attune'}
      };
      const textureMap={
        gentle:{label:'Gentle — fewer layers, more silence',impact:'softer sustain, shorter windows'},
        medium:{label:'Medium — balanced layers and sustain',impact:'moderate sustain, full range'},
        intense:{label:'Intense — deeper resonance, stronger vibrational presence',impact:'longer sustain, lower tones'}
      };
      // mood buttons
      const moodBtns=document.getElementById('moodBtns');
      const methodName=document.getElementById('methodName');
      const methodDesc=document.getElementById('methodDesc');
      const estimated=document.getElementById('estimatedLength');
      const chosenMethod=document.getElementById('chosenMethod');
      const dynamicCta=document.getElementById('dynamicCta');

      moodBtns.addEventListener('click',e=>{
        if(!e.target.dataset.mood) return;
        moodBtns.querySelectorAll('button').forEach(b=>b.classList.remove('active'));
        e.target.classList.add('active');
        const key=e.target.dataset.mood;
        const m=methodMap[key];
        methodName.textContent=m.name;
        methodDesc.textContent=m.desc+' Estimated length: '+m.length+'.';
        estimated.textContent='Estimate: '+m.length;
        chosenMethod.value=m.name;
        dynamicCta.textContent=m.cta;
        // keep href hint for external flows
        dynamicCta.href='{{PRIMARY_CTA_URL}}?method='+encodeURIComponent(m.name)+'&preset='+key;
      });

      // textures (two mixers update the same chosenTexture)
      function setupTexture(id, outId){
